// 1. Status Code Tests
pm.test("verify Status code is 201 - Successful registration", function () {
    pm.response.to.have.status(201);
});

pm.test("verify Status code is not 500 - No server error", function () {
    pm.response.to.not.have.status(500);
});

// 2. Response Time Test
pm.test("verify Response time is less than 3000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(3000);
});

// 3. Response Headers Tests
pm.test("verify Content-Type header is present and contains 'application/json'", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

// 4. Response Body Structure Tests
pm.test("verify Response body is valid JSON", function () {
    pm.response.to.be.json;
});

const jsonData = pm.response.json();

pm.test("verify Response contains 'id' field", function () {
    pm.expect(jsonData).to.have.property("id");
});

pm.test("verify'id' field is a non-empty string", function () {
    pm.expect(jsonData.id).to.be.a("string").and.to.not.be.empty;
});

pm.test("verify Response contains 'first_name' field with value 'John'", function () {
    pm.expect(jsonData).to.have.property("first_name");
    pm.expect(jsonData.first_name).to.eql("John");
});

pm.test("verify Response contains 'last_name' field with value 'Doe'", function () {
    pm.expect(jsonData).to.have.property("last_name");
    pm.expect(jsonData.last_name).to.eql("Doe");
});

pm.test("verify Response contains 'email' field with value 'john@doe.example'", function () {
    pm.expect(jsonData).to.have.property("email");
    pm.expect(jsonData.email).to.eql("john@doe.example");
});

pm.test("verify Response contains 'phone' field", function () {
    pm.expect(jsonData).to.have.property("phone");
});

pm.test("verify Response contains 'dob' field", function () {
    pm.expect(jsonData).to.have.property("dob");
});

pm.test("verify Response contains 'address' object", function () {
    pm.expect(jsonData).to.have.property("address");
    pm.expect(jsonData.address).to.be.an("object");
});

pm.test("verify 'address' object contains required fields", function () {
    const address = jsonData.address;
    pm.expect(address).to.have.property("street");
    pm.expect(address).to.have.property("city");
    pm.expect(address).to.have.property("state");
    pm.expect(address).to.have.property("country");
    pm.expect(address).to.have.property("postal_code");
});

pm.test("verify Password field is NOT returned in the response (security check)", function () {
    pm.expect(jsonData).to.not.have.property("password");
});

// 5. Data Type Validation Tests
pm.test("verify 'id' is a string", function () {
    pm.expect(jsonData.id).to.be.a("string");
});

pm.test("verify 'first_name' is a string", function () {
    pm.expect(jsonData.first_name).to.be.a("string");
});

pm.test("verify 'last_name' is a string", function () {
    pm.expect(jsonData.last_name).to.be.a("string");
});

pm.test("verify 'email' is a string", function () {
    pm.expect(jsonData.email).to.be.a("string");
});

// 6. Email Format Validation Test
pm.test("verify Returned email matches a valid email format", function () {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    pm.expect(jsonData.email).to.match(emailRegex);
});

